// Checkout conversion module - ensures paid events are recorded
const { logEvent } = require('./event-logger');

async function processCheckout(sessionId, amount, currency) {
  // Validate session
  if (!sessionId || !amount) {
    logEvent('checkout_error', { sessionId, reason: 'missing_params' });
    return { success: false, error: 'Missing required parameters' };
  }
  // Record paid event
  const event = {
    type: 'paid_event',
    sessionId,
    amount,
    currency: currency || 'USD',
    timestamp: new Date().toISOString()
  };
  await logEvent('revenue_event', event);
  return { success: true, event };
}

module.exports = { processCheckout };
